package online.wydmeal.reservation;
import android.app.*;
import android.content.*;
import android.content.pm.*;
import android.database.Cursor;
import android.net.Uri;
import android.os.*;
import android.provider.Settings;
import android.widget.*;
import org.json.*;
import java.net.*;
import java.io.*;
import java.security.MessageDigest;
import java.util.*;
import java.util.concurrent.*;

/** Explicit-consent updater with fixed-origin downloads, digest and signing checks. */
public final class UpdateManager {
 private final Activity activity;private final ExecutorService worker=Executors.newSingleThreadExecutor();private final Handler main=new Handler();private boolean checking,closed;private int offered;private TextView status;
 private final BroadcastReceiver downloads=new BroadcastReceiver(){@Override public void onReceive(Context c,Intent intent){long id=activity.getSharedPreferences("updates",0).getLong("downloadId",-1);if(id>0&&id==intent.getLongExtra(DownloadManager.EXTRA_DOWNLOAD_ID,-2))checkDownloaded(true);}};
 public UpdateManager(Activity a){activity=a;IntentFilter filter=new IntentFilter(DownloadManager.ACTION_DOWNLOAD_COMPLETE);if(Build.VERSION.SDK_INT>=33)a.registerReceiver(downloads,filter,Context.RECEIVER_EXPORTED);else a.registerReceiver(downloads,filter);}
 private android.content.SharedPreferences prefs(){return activity.getSharedPreferences("updates",0);}
 public int currentCode(){try{PackageInfo p=activity.getPackageManager().getPackageInfo(activity.getPackageName(),0);return Build.VERSION.SDK_INT>=28?(int)p.getLongVersionCode():p.versionCode;}catch(Exception e){return 0;}}
 public String currentName(){try{return activity.getPackageManager().getPackageInfo(activity.getPackageName(),0).versionName;}catch(Exception e){return "";}}
 private void message(String text){if(status!=null)status.setText(text);}
 public void render(LinearLayout parent,NativeUi ui){ui.title(parent,"检查更新","当前版本 "+currentName());LinearLayout box=ui.card(parent);status=ui.body("点击下方按钮检查是否有新版本。");box.addView(status);String last=prefs().getString("checked","");if(!last.isEmpty()){ui.gap(box,12);box.addView(ui.text("上次检查："+last,13,ui.muted,false));}ui.fullButton(parent,"检查新版本",true,()->check(true));if(prefs().getLong("downloadId",-1)>0){ui.fullButton(parent,"查看下载状态／安装已下载版本",false,()->checkDownloaded(true));ui.fullButton(parent,"打开系统下载列表",false,()->{try{activity.startActivity(new Intent(DownloadManager.ACTION_VIEW_DOWNLOADS));}catch(Exception e){alert("请在系统下载管理中查看。");}});}ui.gap(parent,16);parent.addView(ui.body("只有选择下载后才会下载安装包。安装前会核对文件完整性、应用包名和签名，安装仍需你在系统界面确认。"));}
 public void check(boolean manual){if(checking||closed)return;checking=true;message("正在检查新版本…");worker.execute(()->{try{JSONObject release=fetch();ReleaseInfo info=ReleaseInfo.parse(release);main.post(()->{if(closed||activity.isFinishing())return;checking=false;prefs().edit().putString("checked",java.time.LocalDateTime.now().format(java.time.format.DateTimeFormatter.ofPattern("yyyy-MM-dd HH:mm"))).apply();if(info.code<=currentCode()){message("当前已是最新版本 "+currentName());if(manual)Toast.makeText(activity,"当前已是最新版本",Toast.LENGTH_SHORT).show();}else{message("发现新版本 "+info.name);if(manual||offered!=info.code){offered=info.code;offer(info);}}});}catch(Exception e){main.post(()->{if(closed)return;checking=false;message("检查失败，请检查网络后重试。");if(manual)alert(e.getMessage()==null?"暂时无法检查更新，请稍后重试。":e.getMessage());});}});}
 private JSONObject fetch()throws Exception{HttpURLConnection c=(HttpURLConnection)new URL(ApiClient.ORIGIN+"/android/latest.json").openConnection();c.setConnectTimeout(12000);c.setReadTimeout(12000);c.setInstanceFollowRedirects(false);c.setRequestProperty("Cache-Control","no-cache");c.setRequestProperty("User-Agent","WydMealNative/2.2 Android");try{if(c.getResponseCode()!=200)throw new IOException("更新服务暂时不可用。");try(InputStream input=c.getInputStream()){ByteArrayOutputStream out=new ByteArrayOutputStream();byte[] b=new byte[4096];int n;while((n=input.read(b))!=-1){if(out.size()+n>65536)throw new IOException("更新信息无效。");out.write(b,0,n);}return new JSONObject(out.toString("UTF-8"));}}finally{c.disconnect();}}
 private void offer(ReleaseInfo info){new AlertDialog.Builder(activity).setTitle("发现新版本 "+info.name).setMessage(info.notes+"\n\n安装包 "+String.format(Locale.CHINA,"%.1f MB",info.bytes/1048576d)+"\n是否下载？").setPositiveButton("下载新版",(d,w)->download(info)).setNegativeButton("稍后再说",null).show();}
 private void download(ReleaseInfo info){try{long old=prefs().getLong("downloadId",-1);if(old>0)activity.getSystemService(DownloadManager.class).remove(old);String name="wyd-meal-"+info.code+".apk";File destination=new File(activity.getExternalFilesDir(Environment.DIRECTORY_DOWNLOADS),name);if(destination.exists()&&!destination.delete())throw new IOException("无法替换旧安装包。");DownloadManager.Request request=new DownloadManager.Request(Uri.parse(info.url)).addRequestHeader("User-Agent","WydMealNative/2.2 Android").setTitle("放纵餐预约 "+info.name).setDescription("下载完成后核验安装包").setMimeType("application/vnd.android.package-archive").setNotificationVisibility(DownloadManager.Request.VISIBILITY_VISIBLE_NOTIFY_COMPLETED).setAllowedOverMetered(true).setAllowedOverRoaming(false).setDestinationInExternalFilesDir(activity,Environment.DIRECTORY_DOWNLOADS,name);long id=activity.getSystemService(DownloadManager.class).enqueue(request);prefs().edit().putLong("downloadId",id).putString("release",info.json.toString()).putString("file",name).apply();message("已开始下载，可在系统下载管理查看进度。");Toast.makeText(activity,"已开始下载",Toast.LENGTH_SHORT).show();}catch(Exception e){alert("下载未能开始，请稍后重试。");}}
 public void checkDownloaded(boolean interactive){long id=prefs().getLong("downloadId",-1);if(id<0){if(interactive)alert("还没有下载新版安装包。");return;}try(Cursor cursor=activity.getSystemService(DownloadManager.class).query(new DownloadManager.Query().setFilterById(id))){if(!cursor.moveToFirst()){if(interactive)alert("下载记录已移除，请重新检查更新。");return;}int state=cursor.getInt(cursor.getColumnIndexOrThrow(DownloadManager.COLUMN_STATUS));if(state!=DownloadManager.STATUS_SUCCESSFUL){if(interactive)alert(state==DownloadManager.STATUS_FAILED?"下载失败，请重新检查更新后下载。":"安装包仍在下载，请稍后查看。");return;}}catch(Exception e){if(interactive)alert("暂时无法读取下载状态。");return;}
  worker.execute(()->{try{ReleaseInfo info=ReleaseInfo.parse(new JSONObject(prefs().getString("release","{}")));File file=ApkProvider.file(activity);verifyFile(file,info);main.post(()->{if(closed||activity.isFinishing())return;message("安装包校验通过，可以安装新版。");if(interactive)new AlertDialog.Builder(activity).setTitle("新版已下载").setMessage("版本 "+info.name+"，完整性与签名校验通过。现在安装？").setPositiveButton("安装",(d,w)->install()).setNegativeButton("稍后",null).show();});}catch(Exception e){main.post(()->{if(interactive&&!closed)alert("安装包校验未通过，请删除后重新下载。");});}});
 }
 private void verifyFile(File file,ReleaseInfo info)throws Exception{if(!file.isFile()||file.length()!=info.bytes)throw new IOException("Invalid size");MessageDigest digest=MessageDigest.getInstance("SHA-256");try(InputStream in=new FileInputStream(file)){byte[] b=new byte[65536];int n;while((n=in.read(b))!=-1)digest.update(b,0,n);}if(!hex(digest.digest()).equals(info.sha))throw new IOException("Invalid digest");int flags=Build.VERSION.SDK_INT>=28?PackageManager.GET_SIGNING_CERTIFICATES:PackageManager.GET_SIGNATURES;PackageManager pm=activity.getPackageManager();PackageInfo archive=pm.getPackageArchiveInfo(file.getAbsolutePath(),flags),current=pm.getPackageInfo(activity.getPackageName(),flags);if(archive==null||!activity.getPackageName().equals(archive.packageName)||(Build.VERSION.SDK_INT>=28?archive.getLongVersionCode():archive.versionCode)!=info.code||info.code<=currentCode())throw new IOException("Invalid package");Signature[] next=Build.VERSION.SDK_INT>=28?archive.signingInfo.getApkContentsSigners():archive.signatures,installed=Build.VERSION.SDK_INT>=28?current.signingInfo.getApkContentsSigners():current.signatures;boolean match=false;for(Signature n:next)for(Signature old:installed)if(MessageDigest.isEqual(n.toByteArray(),old.toByteArray()))match=true;if(!match)throw new IOException("Invalid signature");}
 private void install(){if(Build.VERSION.SDK_INT>=26&&!activity.getPackageManager().canRequestPackageInstalls()){new AlertDialog.Builder(activity).setTitle("允许安装应用更新").setMessage("请在系统设置中允许此应用安装更新，然后返回检查更新页继续安装。").setPositiveButton("前往设置",(d,w)->activity.startActivity(new Intent(Settings.ACTION_MANAGE_UNKNOWN_APP_SOURCES,Uri.parse("package:"+activity.getPackageName())))).setNegativeButton("稍后",null).show();return;}try{Uri uri=Uri.parse("content://"+activity.getPackageName()+".apk/update");activity.startActivity(new Intent(Intent.ACTION_VIEW).setDataAndType(uri,"application/vnd.android.package-archive").addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION));}catch(Exception e){alert("无法打开安装器，请在系统文件管理中安装已下载的 APK。");}}
 private void alert(String text){if(!closed&&!activity.isFinishing())new AlertDialog.Builder(activity).setTitle("应用更新").setMessage(text).setPositiveButton("知道了",null).show();}
 public void close(){closed=true;try{activity.unregisterReceiver(downloads);}catch(Exception ignored){}worker.shutdownNow();main.removeCallbacksAndMessages(null);}
 public static String hex(byte[] b){StringBuilder out=new StringBuilder();for(byte value:b)out.append(String.format(Locale.ROOT,"%02x",value&255));return out.toString();}
 public static final class ReleaseInfo {int code;long bytes;String name,url,sha,notes;JSONObject json;
  static ReleaseInfo parse(JSONObject value)throws Exception{ReleaseInfo r=new ReleaseInfo();r.code=value.getInt("versionCode");r.name=value.getString("versionName");r.bytes=value.getLong("bytes");r.sha=value.getString("sha256").toLowerCase(Locale.ROOT);r.url=value.getString("apkUrl");ReleasePolicy.validate(r.code,r.bytes,r.sha,r.url);if(value.optInt("minSdk",26)>Build.VERSION.SDK_INT)throw new IOException("新版需要更高版本的 Android。");JSONArray notes=value.optJSONArray("notes");StringBuilder text=new StringBuilder();if(notes!=null)for(int i=0;i<notes.length();i++)text.append("• ").append(notes.optString(i)).append('\n');r.notes=text.toString();r.json=value;return r;}
 }
}
